sys_script_include.script:
function GetCountrySubdivisionRecord(vSubdivision)
{
	var GetRecord = x_snc_devtools.GetRecord;
	var IsValidRecord = x_snc_devtools.IsValidRecord;
	var GetStringValue = x_snc_devtools.GetStringValue;
	var GetCountryRecord = x_snc_devtools.GetCountryRecord;
	var GetValue = x_snc_devtools.GetValue;



	var grSubdivision = GetRecord('x_snc_geodata_country_subdivision',vSubdivision);
	if (IsValidRecord(grSubdivision) == true)
	{
		return grSubdivision;
	}
	var strCode = GetStringValue(vSubdivision);
	var aCode = strCode.split('-');
	var strCodeCountry = GetStringValue(GetValue(aCode,0));
	var strCodeSubdivision = GetStringValue(GetValue(aCode,1));

	if (strCodeCountry != '' && strCodeSubdivision != '')
	{
		var grCountry = GetCountryRecord(strCodeCountry);
		if (IsValidRecord(grCountry) == true)
		{
			var grSubdivision = new GlideRecord('x_snc_geodata_country_subdivision');
			grSubdivision.addQuery('country','=',grCountry.sys_id);
			grSubdivision.addQuery('iso_3166_2_code','=',strCodeSubdivision);
			grSubdivision.query();
			if (grSubdivision.getRowCount() == 1)
			{
				grSubdivision.next();
				return grSubdivision;
			}
		}
	}

	return false;

}
